package test

import (
	. "github.com/onsi/ginkgo/v2"

	. "github.com/ArtHustle/mock_gen"
)

// --add-header-note prepends the standard "Code generated by MockGen.
// DO NOT EDIT." comment. Tested independently to keep flag-combination
// tests focused on their own feature.
var _ = Describe("Header note", func() {
	DescribeTable("emits the expected mock",
		runGenEntry,

		Entry("prefixes the generated-code header", `
package pkg
type Service interface { DoSomething() }`,
			`// Code generated by MockGen. DO NOT EDIT.

package test

// mockCallAt returns log[i], treating negative i as an offset from the end.
// Out-of-range indices panic (slice semantics).
func mockCallAt[T any](log []T, i int) T {
	if i < 0 {
		i += len(log)
	}
	return log[i]
}

type ServiceMock_DoSomething_Call struct {
}

type ServiceMock struct {
	doSomething_calls_log []ServiceMock_DoSomething_Call
}

func (this *ServiceMock) DoSomething() {
	this.doSomething_calls_log = append(this.doSomething_calls_log, ServiceMock_DoSomething_Call{})
}

func (this *ServiceMock) DoSomething_calls() []ServiceMock_DoSomething_Call {
	out := make([]ServiceMock_DoSomething_Call, len(this.doSomething_calls_log))
	copy(out, this.doSomething_calls_log)
	return out
}

func (this *ServiceMock) DoSomething_call(i int) ServiceMock_DoSomething_Call {
	return mockCallAt(this.doSomething_calls_log, i)
}

func (this *ServiceMock) Reset_history() {
	this.doSomething_calls_log = nil
}
`, Options{AddHeaderNote: true}),
	)
})
